<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {antSlotSource,checkAntOriginal,checkAntReply,ANT_SLOT_PROJECT,ANT_SLOT_PREFAB,ANT_SLOT_NODE,type AntOriginal,type AntReply} from '../domain/ant-slot-binding'
import type {IconHandoff} from '../domain/icon-handoff'
import type {AiJobSnapshot} from '../domain/ai-jobs-read'
import type {AiVariantImportVerification} from '../stores/ai-job-actions'
import {aiJobActionCanonical} from '../domain/ai-job-actions'
const props=defineProps<{project:{id:string;path:string}|null;packet:IconHandoff|null;job:AiJobSnapshot|null;active:boolean;ready:boolean;variantVerification?:AiVariantImportVerification|null}>()
const key='companion-ant-slot-original-v1',source=computed(()=>{const job=props.job,proof=props.variantVerification,imported=job?.variantImport;if(!job||!proof||proof.projectId!==job.projectId||proof.jobId!==job.jobId||proof.revision!==job.revision||proof.requestHash!==job.requestHash||proof.sourceRevision!==job.sourceRevision||proof.operationId!==imported?.operationId||aiJobActionCanonical(proof.artifact)!==aiJobActionCanonical(imported.artifact))return null;return antSlotSource(props.packet,job)}),pending=ref<AntOriginal|null>(null),storageBlocked=ref(false),busy=ref(false),observation=ref<AntReply|null>(null),message=ref(''),approved=ref(false)
function load(){try{const raw=localStorage.getItem(key);pending.value=raw?checkAntOriginal(JSON.parse(raw)):null;storageBlocked.value=false}catch{pending.value=null;storageBlocked.value=true;message.value='原操作恢复记录无法核验，已停止新操作。'}}
load()
const onStorage=(event:StorageEvent)=>{if(event.key===key)load()};globalThis.addEventListener('storage',onStorage);onBeforeUnmount(()=>globalThis.removeEventListener('storage',onStorage))
let epoch=0
watch(()=>[props.project?.id,props.project?.path,source.value?.requestHash,source.value?.revision,source.value?.assetSha256,props.active,props.ready],()=>{epoch++;observation.value=null;approved.value=false},{flush:'sync'})
async function request(action:string,body:unknown,original?:AntOriginal){const response=await fetch(`/api/projects/${ANT_SLOT_PROJECT}/ant-slot-binding/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error('后台未确认操作，请核对原操作，不要重复提交。');return checkAntReply(await response.json(),action,original)}
const available=computed(()=>props.project?.id===ANT_SLOT_PROJECT&&props.active&&props.ready&&!!source.value&&!storageBlocked.value&&!pending.value&&!busy.value)
async function inspect(){if(!available.value||!source.value)return;const token=epoch;busy.value=true;try{const result=await request('inspect',{source:source.value});if(token===epoch){observation.value=result;message.value=result.state==='observed'?'当前槽位已引用此素材；仅为读取观察，不代表本次应用或运行验收。':result.state==='conflict'?'槽位当前素材与预期不一致，已停止应用。':''}}catch{if(token===epoch)message.value='槽位读取失败，请核对 Creator 与已导入素材。'}finally{busy.value=false}}
async function send(action:'open'|'bind'){if(!navigator.locks){message.value='当前浏览器无法安全锁定原操作，未提交。';return}await navigator.locks.request(key,{ifAvailable:true},async lock=>{if(!lock){message.value='另一页面正在处理该槽位，请稍后查询。';return}load();await sendLocked(action)})}
async function sendLocked(action:'open'|'bind'){if(!available.value||!source.value||!observation.value)return;if(action==='open'&&observation.value.state!=='needs_open'||action==='bind'&&(observation.value.state!=='ready'||!observation.value.revision||!approved.value))return
 const original:AntOriginal=action==='open'?{action,source:source.value,operationId:crypto.randomUUID()}:{action,source:source.value,operationId:crypto.randomUUID(),expectedRevision:observation.value.revision!,confirmation:'APPLY_ANT_SLOT_ICON'};try{localStorage.setItem(key,JSON.stringify(original));pending.value=checkAntOriginal(JSON.parse(localStorage.getItem(key)!))}catch{storageBlocked.value=true;message.value='无法可靠保存原操作，未提交。';return}
 const token=epoch;busy.value=true;observation.value=null;approved.value=false;try{const {action:_,...body}=original;const result=await request(action,body,original);if(token===epoch)await finish(result,original)}catch{if(token===epoch)message.value='结果尚未确认。请查询原操作，系统不会重发。'}finally{busy.value=false}}
async function finish(result:AntReply,original:AntOriginal){if((original.action==='bind'&&result.state==='applied')||(original.action==='open'&&result.state==='ready')){const raw=localStorage.getItem(key);if(!raw||JSON.stringify(checkAntOriginal(JSON.parse(raw)))!==JSON.stringify(original))throw Error('原操作记录不匹配');localStorage.removeItem(key);pending.value=null;message.value=original.action==='bind'?'扩充槽位已应用并保存；仍需在游戏中验收。':'目标已打开，请重新读取槽位后确认应用。';observation.value=original.action==='bind'?result:null}else message.value='原操作结果尚未确认。请查询原操作，系统不会重发。'}
async function status(){if(!pending.value||busy.value||props.project?.id!==ANT_SLOT_PROJECT)return;const original=pending.value,token=epoch;busy.value=true;try{const result=await request('status',{original},original);if(token===epoch)await finish(result,original)}catch{if(token===epoch)message.value='查询失败或回执无法核验；原操作保留，不会重发。'}finally{busy.value=false}}
</script>
<template><section v-if="project?.id===ANT_SLOT_PROJECT" aria-label="应用到扩充槽位" class="slot-binding"><h4>应用到扩充槽位</h4><p>固定目标：{{ ANT_SLOT_PREFAB }} · {{ ANT_SLOT_NODE }}。仅支持已导入的 160 × 160 扩充槽位图标。</p><p v-if="!source&&!pending" role="status">请先核对尺寸导入原操作及任务回执，再准备对应的交接包。</p><p v-if="storageBlocked" role="alert">原操作记录无法核验，请保留记录并排查。</p><button :disabled="!available" @click="inspect">读取槽位状态</button><button v-if="observation?.state==='needs_open'" :disabled="!available" @click="send('open')">打开目标预制体</button><template v-if="observation?.state==='ready'"><label><input v-model="approved" type="checkbox">我已核对该槽位与当前图标，确认应用并保存</label><button :disabled="!available||!approved" @click="send('bind')">应用到扩充槽位</button></template><button v-if="pending" :disabled="busy" @click="status">查询原操作结果</button><p v-if="message" role="status">{{ message }}</p></section></template>
<style scoped>.slot-binding{display:grid;gap:8px;padding:12px;border:1px solid var(--el-border-color);border-radius:6px}.slot-binding p,.slot-binding h4{margin:0}</style>
